  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec4 fragColor = 0;
vec2 fragCoord  = uv;
// CONV: Center on screen, then try some uAspect correction
