vec3 camDir = camPos+vec3(-1.25,0.1, 1.);
mat3 cam = camera(camPos, camDir, 0.);
vec3 rayDir = multiply(cam, normalize(vec3(uv, 0.8)));
Ray ray;
ray.ro = camPos;
ray.rd = rayDir;
ray.rd.x -= 0.03;
