ray.ro.y += sin(uTime*0.2) * 5.0;
//ray.rd.y += fac;
vec4 col = render(ray);
ret = vec4(1.-col.xyz,clamp(1.-col.w/MAXDIST, 0., 1.));
  fragColor = vec4(ret, 1.0);
}

